#__PDP_MODAL_SCOPE__ .product-detail-container {
  flex-direction: row;
  background-color: transparent;
  --pdp-collapse-breakpoint: 320px;
  --pdp-details-max-width: 480px;
  --pdp-details-min-width: 320px;
  --pdp-container-collapse-breakpoint: 900px;
  container-type: inline-size;

}
/* Collapsed state when container width is less than breakpoint (container-based, not viewport) */
@container (max-width: 900px) {
  #__PDP_MODAL_SCOPE__ .product-detail-container {
    flex-direction: column !important;
    gap: 40px !important;
    align-items: stretch !important;
    justify-content: flex-start !important;
  }
  #__PDP_MODAL_SCOPE__ .hl-product-image-container {
    width: 100% !important;
    max-width: 100% !important;
    min-width: 100% !important;
    flex-shrink: 0 !important;
    flex-grow: 0 !important;
    flex-basis: 100% !important;
    position: relative !important;
    top: 0 !important;
    height: auto !important;
    overflow: hidden !important;
    order: 0 !important;
  }
  #__PDP_MODAL_SCOPE__ .hl-product-image-container .image-wrapper {
    width: 100% !important;
    max-width: 100% !important;
    min-width: 100% !important;
    box-sizing: border-box !important;
    overflow: hidden !important;
  }
  #__PDP_MODAL_SCOPE__ .c-product-details {
    width: 100% !important;
    max-width: 100% !important;
    min-width: 100% !important;
    flex-shrink: 0 !important;
    flex-grow: 0 !important;
    flex-basis: 100% !important;
    box-sizing: border-box !important;
    order: 0 !important;
    container-type: inline-size;
  }
  #__PDP_MODAL_SCOPE__ .hl-product-image {
    width: 100% !important;
    height: auto !important;
    aspect-ratio: 1 !important;
    object-fit: cover !important;
  }
}
/* Normal side-by-side layout when container is wide enough (container-based, not viewport) */
@container (min-width: 901px) {
  #__PDP_MODAL_SCOPE__ .product-detail-container {
    flex-direction: row !important;
    justify-content: left !important;
    gap: 40px !important;
  }
  #__PDP_MODAL_SCOPE__ .hl-product-image-container {
    width: 50% !important;
    flex-shrink: 0 !important;
    flex-grow: 0 !important;
    min-width: 50% !important;
    max-width: 50% !important;
    order: 1 !important;
  }
  #__PDP_MODAL_SCOPE__ .c-product-details {
    width: calc(100% - 50% - 40px) !important;
    min-width: 320px !important;
    max-width: 625px !important;
    flex-shrink: 1 !important;
    flex-grow: 0 !important;
    flex-basis: auto !important;
    order: 2 !important;
    container-type: inline-size;
  }
  #__PDP_MODAL_SCOPE__ .hl-product-image {
    width: 100% !important;
    height: auto !important;
    aspect-ratio: 1 !important;
    object-fit: cover !important;
  }
  #__PDP_MODAL_SCOPE__ .quantity-container {
    width: 100% !important;
    max-width: 464px !important;
  }
}
