}
/* Container query: When product details container is less than 213px, show 1 variant column instead of 2 */
@container (max-width: 213px) {
  #__PDP_MODAL_SCOPE__ .variants-wrapper {
    display: grid !important;
    grid-template-columns: repeat(1, minmax(0, 1fr)) !important;
    gap: 10px !important;
  }
  #__PDP_MODAL_SCOPE__ .variants-container {
    padding-right: 0 !important;
    min-width: 100% !important;
  }
  #__PDP_MODAL_SCOPE__ .quantity-container {
    width: 100% !important;
    max-width: 464px !important;
  }
}
#__PDP_MODAL_SCOPE__ .primary-btn {
  background-color: #c7ae82ff;
  color: #ffffff;
  border: 1px solid transparent;
  transition: box-shadow 0.1s ease-in-out, transform 0.3s ease-in-out;
  max-width: 464px;
}
  #__PDP_MODAL_SCOPE__ .primary-btn:hover {
  box-shadow: 0px 0px 1px 1px #c7ae82ff;
}
/* BEM base+modifier chained selector. PDP pills carry both
   `.ec-subscription-pill` and `.ec-subscription-pill--pdp`; chaining the
   two in the selector scopes this rule to PDP-context pills only AND bumps
   specificity to (1,2,0) — beating any ancestor PLP/FP rule (1,1,0) that
   still targets the base class when the PDP renders inside the in-canvas
   quick-view modal in the page-builder editor. */
#__PDP_MODAL_SCOPE__ .ec-subscription-pill.ec-subscription-pill--pdp {
  font-size: 12px;
  font-weight: 500;
  padding: 2px 10px;
  border-radius: 9999px;
  background: #FFF4ED;
  color: #E62E05;
}
#__PDP_MODAL_SCOPE__ .ec-subscription-description {
  color: var(--brandboards-new_color_7895);
  font-size: 12px;
  font-family: var(--headlinefont);
}
#__PDP_MODAL_SCOPE__ .secondary-btn {
  background-color: transparent;
  color: #000000cf;
  border: 1px solid #000000cf;
  transition: box-shadow 0.1s ease-in-out, transform 0.3s ease-in-out;
  max-width: 464px;
}
#__PDP_MODAL_SCOPE__ .secondary-btn:hover {
