  gap: 16px;
}
  #__PDP_MODAL_SCOPE__ .ec-review-stars {
    color: #000000;
  }
  #__PDP_MODAL_SCOPE__ .ec-full-star, .ec-half-star {
    fill: #FDB022;
  }
